import{_ as d,o as r,c as a,a2 as e}from"./chunks/framework.CHeM0PsO.js";const c=JSON.parse('{"title":"04b · 蜂蜜黄油味「声纹测试」20 秒加长版","description":"","frontmatter":{},"headers":[],"relativePath":"lab/shuangyu-fries/honey-butter/04b-20s-storyboard.md","filePath":"lab/shuangyu-fries/honey-butter/04b-20s-storyboard.md","lastUpdated":1787456457000}'),o={name:"lab/shuangyu-fries/honey-butter/04b-20s-storyboard.md"};function s(h,t,n,l,i,b){return r(),a("div",null,[...t[0]||(t[0]=[e(`<h1 id="_04b-·-蜂蜜黄油味「声纹测试」20-秒加长版" tabindex="-1">04b · 蜂蜜黄油味「声纹测试」20 秒加长版 <a class="header-anchor" href="#_04b-·-蜂蜜黄油味「声纹测试」20-秒加长版" aria-label="Permalink to &quot;04b · 蜂蜜黄油味「声纹测试」20 秒加长版&quot;">​</a></h1><blockquote><p>阶段 4 · 互动感官片 20 秒变体 ｜ 2026-08-23 ｜ 9:16 竖屏 ｜ 12 秒主版的加长版本</p></blockquote><h2 id="结论先行" tabindex="-1">结论先行 <a class="header-anchor" href="#结论先行" aria-label="Permalink to &quot;结论先行&quot;">​</a></h2><p>12 秒主版的强度来自「密度」：0.9 秒出第一声、4.2 秒内跑完 A / B / C、8 秒出头揭晓反转。直接按比例拉长每一镜，只会稀释这份密度，反而更弱。</p><p>所以 20 秒版<strong>不碰前半段</strong>（00:00–08.7 秒基本沿用 12 秒版），把多出来的约 8 秒全部放到反转之后，做成两件事：</p><ol><li><strong>证明反转</strong>：慢放三条波形 + 同一个断面，把「答案：都是」从一句玩笑变成产品证据。</li><li><strong>邀请参与</strong>：加宽作答停留、新增评论区钩子、给落版更多呼吸，把「看完」升级成「评论 + 下一条」。</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>前半（0–8.7s）基本不变：出题 → A → B → C → 作答 → remix → 答案</span></span>
<span class="line"><span>后半（8.7–20s）新增：慢放证据 → 一种脆 → 续拍钩子 → 落版</span></span></code></pre></div><p><strong>零新增关键帧</strong>：全部复用既有的 10 张关键帧和 4 段动态素材，只改剪辑、后期波形、文案和声音节拍。</p><h2 id="与-12-秒版的关系" tabindex="-1">与 12 秒版的关系 <a class="header-anchor" href="#与-12-秒版的关系" aria-label="Permalink to &quot;与 12 秒版的关系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>12 秒主版</th><th>本 20 秒加长版</th></tr></thead><tbody><tr><td>创意命题</td><td>「哪一声是蜂蜜黄油味？答案：都是」</td><td>不变</td></tr><tr><td>前半（0–8.7s）</td><td>出题 → A/B/C → 作答 → remix → 答案</td><td>基本不变，仅作答窗口加宽</td></tr><tr><td>后半（8.7s–尾）</td><td>证据 + 落版快速收尾（约 3.9s）</td><td>证明 + 参与钩子 + 落版（约 11.3s）</td></tr><tr><td>关键帧</td><td>10 张</td><td>复用同 10 张，不新增</td></tr><tr><td>新增成本</td><td>—</td><td>只增加后期合成与声音节拍，无新生成</td></tr></tbody></table><h2 id="_20-秒时间线" tabindex="-1">20 秒时间线 <a class="header-anchor" href="#_20-秒时间线" aria-label="Permalink to &quot;20 秒时间线&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时间</th><th>镜头</th><th>画面与动作</th><th>生成 / 后期</th><th>屏幕文字</th></tr></thead><tbody><tr><td>00:00.0–00:00.9</td><td>01 · 出题</td><td>杯装产品局部占下半部，三根薯条脆竖向露出</td><td>KF01 数字推近；包装与问题后期合成</td><td><strong>戴耳机。哪一声是蜂蜜黄油味？</strong></td></tr><tr><td>00:00.9–00:01.9</td><td>02 · A 声纹</td><td>单根产品从中央折断</td><td>KF02A / B 图生视频</td><td><strong>A</strong></td></tr><tr><td>00:01.9–00:03.0</td><td>03 · B 声纹</td><td>两根产品先后折断</td><td>KF03A / B 图生视频</td><td><strong>B</strong></td></tr><tr><td>00:03.0–00:04.2</td><td>04 · C 声纹</td><td>人物下半脸局部咬下一小段</td><td>KF04A / B 图生视频</td><td><strong>C</strong></td></tr><tr><td>00:04.2–00:06.0</td><td>05 · 作答</td><td>中央产品静止，三条波形纵向并列</td><td>KF05 + 后期真实波形</td><td><strong>你选哪一声？</strong> / 5.2s 起：<strong>答案发在评论区</strong></td></tr><tr><td>00:06.0–00:08.7</td><td>06 · remix</td><td>A、B、C、断面四个动作按四拍重组</td><td>复用镜头 02–04、08，不新生成复合动作</td><td>无</td></tr><tr><td>00:08.7–00:09.6</td><td>07 · 答案</td><td>三条波形合一，画面停住</td><td>复用 KF05，后期动效</td><td><strong>答案：都是。</strong></td></tr><tr><td>00:09.6–00:11.5</td><td>08 · 证据</td><td>断面轻转；三条波形并列慢放叠影</td><td>复用 KF08 + DV02/03/04 静帧回环</td><td>无（留给下一句）</td></tr><tr><td>00:11.5–00:12.7</td><td>09 · 收束</td><td>中央产品静止，一记最干净主咔嚓</td><td>复用 KF05 静帧 + 声音</td><td><strong>不是三种口味，是同一种脆。</strong></td></tr><tr><td>00:12.7–00:16.4</td><td>10 · 续拍钩子</td><td>中央产品静止，留白供评论</td><td>复用 KF05，后期文字</td><td><strong>还想听一根、两根，还是三根？</strong> / <strong>评论区告诉你</strong></td></tr><tr><td>00:16.4–00:20.0</td><td>11 · 落版</td><td>终稿包装、三根产品和少量碎屑稳定落版</td><td>KF09 + 包装后期合成</td><td><strong>双宇食品 · 薯条脆</strong> / <strong>蜂蜜黄油味</strong> / <strong>味道听不见，脆可以。</strong></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">前 6.0 秒不加模型音乐</p><p>视频模型如自动生成声音，一律只作动作同步参考，不进入正式混音。A / B / C 的最终声音在 <a href="./05-sound-edit">05 · 声音与剪辑</a> 独立完成。20 秒版新增的 08–10 段仍沿用这一规则，续拍钩子故意只留 room tone，不放音乐。</p></div><h2 id="逐镜执行" tabindex="-1">逐镜执行 <a class="header-anchor" href="#逐镜执行" aria-label="Permalink to &quot;逐镜执行&quot;">​</a></h2><p>镜头 01、02、03、04、07 与 12 秒版完全一致，执行见 <a href="./04-storyboard">04 · 分镜</a>。这里只写有改动和新增的镜头。</p><h3 id="_05-·-作答-加宽" tabindex="-1">05 · 作答（加宽） <a class="header-anchor" href="#_05-·-作答-加宽" aria-label="Permalink to &quot;05 · 作答（加宽）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>执行</th></tr></thead><tbody><tr><td>输入</td><td>KF05 + A / B / C 最终声音</td></tr><tr><td>方式</td><td>后期动效，不做视频生成</td></tr><tr><td>运动</td><td>三条波形以相同缩放从左向右播放一次，中央产品不动</td></tr><tr><td>改动</td><td>作答窗口由 1.2s 加宽到 1.8s；5.2 秒叠加一句「答案发在评论区」小字，不额外做动画</td></tr><tr><td>重点</td><td>给观众真实的比较与输入时间，不催答案</td></tr><tr><td>废片</td><td>装饰性假波形、某选项被提前高亮、文字遮挡产品</td></tr></tbody></table><h3 id="_08-·-证据·慢放对比" tabindex="-1">08 · 证据·慢放对比 <a class="header-anchor" href="#_08-·-证据·慢放对比" aria-label="Permalink to &quot;08 · 证据·慢放对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>执行</th></tr></thead><tbody><tr><td>输入</td><td>KF08 + DV02 / DV03 / DV04 各 2–4 帧静帧回环</td></tr><tr><td>方式</td><td>后期合成，不做视频生成</td></tr><tr><td>运动</td><td>KF08 断面轻微回正；三条真实波形（A / B / C）在下方一排并列，各自挂一帧对应动作的慢放叠影</td></tr><tr><td>重点</td><td>三条声音的差异来自「动作与数量」，不是口味；同一个 M0 断面证明是同一款产品</td></tr><tr><td>废片</td><td>波形是装饰假波形、慢放帧与动作不对应、字幕抢在 09 之前出现</td></tr></tbody></table><h3 id="_09-·-收束·同一种脆" tabindex="-1">09 · 收束·同一种脆 <a class="header-anchor" href="#_09-·-收束·同一种脆" aria-label="Permalink to &quot;09 · 收束·同一种脆&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>执行</th></tr></thead><tbody><tr><td>输入</td><td>KF05 静帧 + 最干净的一条主咔嚓</td></tr><tr><td>方式</td><td>静帧后期，不生成</td></tr><tr><td>运动</td><td>画面锁定；只在文案出现时切进一声单独的、最干净的主咔嚓</td></tr><tr><td>重点</td><td>把反转落回正向产品主张（酥脆），而不是让人以为被戏弄</td></tr><tr><td>废片</td><td>重复使用 A / B / C 原声、文案超过一行、出现蜂蜜滴淋或黄油块暗示</td></tr></tbody></table><h3 id="_10-·-续拍钩子" tabindex="-1">10 · 续拍钩子 <a class="header-anchor" href="#_10-·-续拍钩子" aria-label="Permalink to &quot;10 · 续拍钩子&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>执行</th></tr></thead><tbody><tr><td>输入</td><td>KF05 静帧</td></tr><tr><td>方式</td><td>静帧后期，轻提示音 + room tone</td></tr><tr><td>运动</td><td>画面锁定，无音乐</td></tr><tr><td>重点</td><td>用真实问题邀请评论，不预设答案、不伪造评论</td></tr><tr><td>废片</td><td>出现假评论截图、出现「最脆/全网最响」等绝对化用词、钩子时间过长让观众以为片已结束</td></tr></tbody></table><h3 id="_11-·-落版-加宽" tabindex="-1">11 · 落版（加宽） <a class="header-anchor" href="#_11-·-落版-加宽" aria-label="Permalink to &quot;11 · 落版（加宽）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>执行</th></tr></thead><tbody><tr><td>输入</td><td>KF09 + 客户确认包装工程文件</td></tr><tr><td>方式</td><td>静帧后期合成；数字推近不超过 2%</td></tr><tr><td>改动</td><td>落版由 1.7s 加宽到 3.6s，品牌、口味与核心文案分层出现，各自至少保留 1.2s</td></tr><tr><td>重点</td><td>包装正面准确、三根 P0 产品构图稳定、最后一声接回片头形成循环</td></tr><tr><td>废片</td><td>模型重绘包装、logo 或中文漂移、碎屑遮字、最后仍有动态变形</td></tr></tbody></table><h2 id="复用与新增资产" tabindex="-1">复用与新增资产 <a class="header-anchor" href="#复用与新增资产" aria-label="Permalink to &quot;复用与新增资产&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资产</th><th>来源</th><th>本 20 秒版用途</th></tr></thead><tbody><tr><td>KF01–KF09</td><td><a href="./02-keyframes">02 · 关键帧</a></td><td>全部复用</td></tr><tr><td>DV02 / DV03 / DV04 / DV08</td><td><a href="./03-demo-preview">03 · Demo 预览</a></td><td>02/03/04/06 直接复用；DV08 兼作 08 慢放底</td></tr><tr><td>P0 身份母版 / M0 断面</td><td>通过审核后补路径</td><td>身份与断面约束不变</td></tr><tr><td>包装工程文件</td><td>客户确认终稿</td><td>仅 11 落版后期合成</td></tr></tbody></table><p><strong>本页零新增关键帧、零新增视频生成。</strong> 20 秒版的全部增量都在剪辑节奏、后期波形、文案分层和声音节拍上。</p><h2 id="声音与剪辑节拍" tabindex="-1">声音与剪辑节拍 <a class="header-anchor" href="#声音与剪辑节拍" aria-label="Permalink to &quot;声音与剪辑节拍&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时间</th><th>剪辑职责</th><th>声音处理</th></tr></thead><tbody><tr><td>00:00.0–00:00.9</td><td>建立问题与口味身份</td><td>0.1 秒提示音后留白</td></tr><tr><td>00:00.9–00:04.2</td><td>A / B / C 连续测试</td><td>不加音乐和转场音；声音峰值逐帧对齐动作</td></tr><tr><td>00:04.2–00:06.0</td><td>加宽作答窗口</td><td>三声尾音以极低音量快速回放，不强调某一选项</td></tr><tr><td>00:06.0–00:08.7</td><td>A–B–C–断面 remix</td><td>音乐第一次进入；第四拍最重，主咔嚓高于伴奏</td></tr><tr><td>00:08.7–00:09.6</td><td>答案停顿</td><td>先静音 0.1 秒，再用轻提示音揭晓</td></tr><tr><td>00:09.6–00:11.5</td><td>慢放证据对比</td><td>A / B / C 三条声音以低音量、慢速叠放，只作证明不作重测</td></tr><tr><td>00:11.5–00:12.7</td><td>收束</td><td>单独回放最干净的一声主咔嚓</td></tr><tr><td>00:12.7–00:16.4</td><td>续拍钩子</td><td>轻提示音 + 干爽 room tone，<strong>故意不放音乐</strong>留评论空间</td></tr><tr><td>00:16.4–00:20.0</td><td>落版与循环</td><td>音乐在产品名出现时收住；19.4 秒最后一声接回片头</td></tr></tbody></table><h2 id="自省-答案时点后移的风险" tabindex="-1">自省：答案时点后移的风险 <a class="header-anchor" href="#自省-答案时点后移的风险" aria-label="Permalink to &quot;自省：答案时点后移的风险&quot;">​</a></h2><p>20 秒版把答案从 8.1 秒推到 8.7–9.6 秒揭晓，仍落在短视频前 10 秒反转的窗口内，但比 12 秒版更晚。<a href="./06-release-review">06 · 发布与验收</a> 的 A/B 测试 C / D 版本（5.5s 早揭晓 vs 8.2s 晚揭晓）已经提示：<strong>答案时点直接影响重播与完播</strong>。</p><p>因此 20 秒版需单独跑一次答案早 / 晚对照。若晚揭晓拖累完播，优先压缩 05 作答或 08 慢放，把答案前移，而不是砍掉 09 收束和 10 续拍钩子这两处真正的新增价值。</p><p><strong>可压缩缓冲区</strong>：10 续拍钩子（3.7s）与 11 落版（3.6s）是全片最可压缩的两段。若投放数据要求收短，可剪成约 15 秒中间版——保留到 09 收束后直接落版，砍掉续拍钩子。</p><h2 id="本步审核" tabindex="-1">本步审核 <a class="header-anchor" href="#本步审核" aria-label="Permalink to &quot;本步审核&quot;">​</a></h2><ul><li>[ ] 前半 0–8.7s 与 12 秒版节奏一致，0.9 秒出第一声、4.2 秒内完成 A / B / C 不被破坏</li><li>[ ] 后半新增的 08–10 只复用既有关键帧，没有为加长而新增生成或改变产品身份</li><li>[ ] A / B / C 使用同一 P0 产品身份，动作与最终声音严格同步</li><li>[ ] 三条波形由最终采用的声音生成，不是装饰性假波形</li><li>[ ] 续拍钩子只做真实提问，不伪造评论、不预设结果</li><li>[ ] 落版品牌、口味与核心文案清晰保留 1.2 秒以上，最后一声可自然循环回片头</li><li>[ ] 全片无蜂蜜滴淋、黄油包裹、油光，无绝对化与营养功效表述</li><li>[ ] 包装只使用客户确认的蜂蜜黄油味终稿物料</li></ul><hr><p><strong>上一版</strong> ← <a href="./04-storyboard">12 秒主版分镜</a> ｜ <strong>下一步</strong> → <a href="./05-sound-edit">05 · 声音与剪辑</a> ｜ <strong>项目首页</strong> ← <a href="./">蜂蜜黄油味独立创意片总览</a></p>`,38)])])}const u=d(o,[["render",s]]);export{c as __pageData,u as default};
